CREATE TABLE "habits" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "target_per_week" INTEGER NOT NULL DEFAULT 7, "reminder_enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("reminder_enabled" IN (0, 1)), "reminder_time" TEXT NULL, "archived_at" INTEGER NULL, "deleted_at" INTEGER NULL);
CREATE TABLE "habit_completions" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "habit_id" INTEGER NOT NULL REFERENCES habits (id) ON DELETE CASCADE, "date" TEXT NOT NULL);
CREATE TABLE "notebooks" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "color_value" INTEGER NOT NULL DEFAULT 4287280376, "icon" TEXT NOT NULL DEFAULT '📓', "order_index" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "archived_at" INTEGER NULL, "deleted_at" INTEGER NULL, "is_favorite" INTEGER NOT NULL DEFAULT 0 CHECK ("is_favorite" IN (0, 1)));
CREATE TABLE "notes" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "notebook_id" INTEGER NULL REFERENCES notebooks (id) ON DELETE SET NULL, "title" TEXT NOT NULL DEFAULT '', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "archived_at" INTEGER NULL, "deleted_at" INTEGER NULL, "is_template" INTEGER NOT NULL DEFAULT 0 CHECK ("is_template" IN (0, 1)), "is_favorite" INTEGER NOT NULL DEFAULT 0 CHECK ("is_favorite" IN (0, 1)), "cover_block_id" INTEGER NULL);
CREATE TABLE "task_lists" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "color_value" INTEGER NOT NULL DEFAULT 4287280376, "order_index" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "archived_at" INTEGER NULL, "deleted_at" INTEGER NULL, "source_note_id" INTEGER NULL REFERENCES notes (id) ON DELETE CASCADE, "auto_archive_completed" INTEGER NOT NULL DEFAULT 0 CHECK ("auto_archive_completed" IN (0, 1)));
CREATE TABLE "list_sections" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "list_id" INTEGER NOT NULL REFERENCES task_lists (id) ON DELETE CASCADE, "name" TEXT NOT NULL, "order_index" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "note_blocks" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "note_id" INTEGER NOT NULL REFERENCES notes (id) ON DELETE CASCADE, "type" TEXT NOT NULL, "content" TEXT NULL, "checked" INTEGER NOT NULL DEFAULT 0 CHECK ("checked" IN (0, 1)), "order_index" INTEGER NOT NULL DEFAULT 0, "heading_level" INTEGER NOT NULL DEFAULT 0, "highlighted" INTEGER NOT NULL DEFAULT 0 CHECK ("highlighted" IN (0, 1)), "bold" INTEGER NOT NULL DEFAULT 0 CHECK ("bold" IN (0, 1)), "italic" INTEGER NOT NULL DEFAULT 0 CHECK ("italic" IN (0, 1)), "collapsed" INTEGER NOT NULL DEFAULT 0 CHECK ("collapsed" IN (0, 1)), "indent" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "tasks" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "title" TEXT NOT NULL, "note" TEXT NULL, "due_date" TEXT NULL, "priority" INTEGER NOT NULL DEFAULT 1, "is_completed" INTEGER NOT NULL DEFAULT 0 CHECK ("is_completed" IN (0, 1)), "created_at" INTEGER NOT NULL, "due_time" TEXT NULL, "reminder_enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("reminder_enabled" IN (0, 1)), "reminder_lead_times" TEXT NULL, "list_id" INTEGER NULL REFERENCES task_lists (id) ON DELETE SET NULL, "section_id" INTEGER NULL REFERENCES list_sections (id) ON DELETE SET NULL, "duration_minutes" INTEGER NULL, "archived_at" INTEGER NULL, "deleted_at" INTEGER NULL, "source_note_block_id" INTEGER NULL REFERENCES note_blocks (id) ON DELETE CASCADE);
CREATE TABLE "labels" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "color_value" INTEGER NOT NULL DEFAULT 4289113068, "order_index" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "task_labels" ("task_id" INTEGER NOT NULL REFERENCES tasks (id) ON DELETE CASCADE, "label_id" INTEGER NOT NULL REFERENCES labels (id) ON DELETE CASCADE, PRIMARY KEY ("task_id", "label_id"));
CREATE TABLE "custom_trackers" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "description" TEXT NULL, "template_type" TEXT NOT NULL, "icon" TEXT NOT NULL, "color_value" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, "reminder_enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("reminder_enabled" IN (0, 1)), "reminder_time" TEXT NULL, "is_template" INTEGER NOT NULL DEFAULT 0 CHECK ("is_template" IN (0, 1)), "archived_at" INTEGER NULL, "deleted_at" INTEGER NULL);
CREATE TABLE "tracker_items" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "tracker_id" INTEGER NOT NULL REFERENCES custom_trackers (id) ON DELETE CASCADE, "name" TEXT NOT NULL, "field_type" TEXT NOT NULL, "sort_order" INTEGER NOT NULL);
CREATE TABLE "tracker_logs" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "tracker_id" INTEGER NOT NULL REFERENCES custom_trackers (id) ON DELETE CASCADE, "logged_date" TEXT NOT NULL, "notes" TEXT NULL, "created_at" INTEGER NOT NULL);
CREATE TABLE "tracker_log_values" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "log_id" INTEGER NOT NULL REFERENCES tracker_logs (id) ON DELETE CASCADE, "item_id" INTEGER NOT NULL REFERENCES tracker_items (id) ON DELETE CASCADE, "value_text" TEXT NOT NULL);
CREATE TABLE "exercise_library" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "primary_muscle" TEXT NOT NULL, "secondary_muscles" TEXT NULL, "equipment" TEXT NOT NULL, "is_custom" INTEGER NOT NULL DEFAULT 0 CHECK ("is_custom" IN (0, 1)));
CREATE TABLE "programs" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "description" TEXT NULL, "is_active" INTEGER NOT NULL DEFAULT 0 CHECK ("is_active" IN (0, 1)), "split_type" TEXT NOT NULL DEFAULT 'rotating', "is_template" INTEGER NOT NULL DEFAULT 0 CHECK ("is_template" IN (0, 1)), "created_at" INTEGER NOT NULL);
CREATE TABLE "program_sessions" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "program_id" INTEGER NOT NULL REFERENCES programs (id) ON DELETE CASCADE, "name" TEXT NOT NULL, "color_value" INTEGER NOT NULL DEFAULT 4284960932, "order_index" INTEGER NOT NULL DEFAULT 0, "week_days" TEXT NULL);
CREATE TABLE "workout_sessions" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NULL, "date" TEXT NOT NULL, "notes" TEXT NULL, "created_at" INTEGER NOT NULL, "program_session_id" INTEGER NULL REFERENCES program_sessions (id) ON DELETE SET NULL);
CREATE TABLE "workout_sets" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "session_id" INTEGER NOT NULL REFERENCES workout_sessions (id) ON DELETE CASCADE, "exercise_id" INTEGER NULL REFERENCES exercise_library (id) ON DELETE SET NULL, "exercise_name" TEXT NOT NULL, "set_number" INTEGER NOT NULL, "reps" INTEGER NULL, "weight_kg" REAL NULL, "duration_seconds" INTEGER NULL, "rest_seconds" INTEGER NULL, "rpe" INTEGER NULL, "is_warmup" INTEGER NOT NULL DEFAULT 0 CHECK ("is_warmup" IN (0, 1)), "is_pr" INTEGER NOT NULL DEFAULT 0 CHECK ("is_pr" IN (0, 1)));
CREATE TABLE "program_exercises" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "program_session_id" INTEGER NOT NULL REFERENCES program_sessions (id) ON DELETE CASCADE, "exercise_id" INTEGER NULL REFERENCES exercise_library (id) ON DELETE SET NULL, "exercise_name" TEXT NOT NULL, "target_sets" INTEGER NOT NULL DEFAULT 3, "target_reps" INTEGER NOT NULL DEFAULT 10, "rest_seconds" INTEGER NOT NULL DEFAULT 120, "order_index" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "work_shifts" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "date" TEXT NOT NULL, "shift_type" TEXT NOT NULL, "start_time" TEXT NOT NULL, "end_time" TEXT NOT NULL, "rotation_label" TEXT NULL, "rotation_color" INTEGER NULL, UNIQUE ("date"));
CREATE TABLE "shift_rotations" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "color_value" INTEGER NOT NULL DEFAULT 4294201630, "order_index" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "muscle_targets" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "group_key" TEXT NOT NULL, "frequency" INTEGER NOT NULL DEFAULT 2, "sets_per_session" INTEGER NOT NULL DEFAULT 3, "compensation_step" INTEGER NOT NULL DEFAULT 1, "order_index" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "home_blocks" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "type" TEXT NOT NULL, "order_index" INTEGER NOT NULL DEFAULT 0, "config_json" TEXT NULL);
